file_editor: {"command": "create", "file_text": "import os
import re
import glob
import pytesseract
from PIL import Image, ImageOps, ImageFilter
from openpyxl import Workbook

IMG_DIR = "/app/workspace/dataset/img"
OUT_XLSX = "/app/workspace/stat_ocr.xlsx"

MONTHS = {
    'jan': 1, 'feb': 2, 'mar': 3, 'apr': 4, 'may': 5, 'jun': 6,
    'jul': 7, 'aug': 8, 'sep': 9, 'sept': 9, 'oct': 10, 'nov': 11, 'dec': 12,
}

# Priority tiers (higher index = higher priority)
TIER_KEYWORDS = [
    # Tier 0 (lowest): TOTAL / AMOUNT etc
    ["TOTAL DUE", "AMOUNT DUE", "BALANCE DUE", "NETT TOTAL", "NET TOTAL", "TOTAL", "AMOUNT"],
    # Tier 1
    ["TOTAL AMOUNT"],
    # Tier 2
    ["TOTAL RM", "TOTAL: RM"],
    # Tier 3 (highest)
    ["GRAND TOTAL"],
]

EXCLUSION_KEYWORDS = [
    "SUBTOTAL", "SUB TOTAL", "TAX", "GST", "SST", "DISCOUNT", "CHANGE", "CASH TENDERED",
]

PAYMENT_EXCLUDE = ["PAYMENT", "TENDERED", "CARD", "RECEIVED", "CASH", "VISA", "MASTERCARD", "ROUNDING", "ROUNDED"]

NUM_RE = re.compile(r"(?<![\d.])\d{1,3}(?:,\d{3})*\.\d{2}(?![\d])|(?<![\d.])\d+\.\d{2}(?![\d])")


def ocr_variants(path):
    """Yield (variant_name, text) pairs."""
    img = Image.open(path)
    # Default
    yield "default", pytesseract.image_to_string(img)
    # Grayscale + autocontrast
    g = ImageOps.autocontrast(img.convert("L"))
    yield "gray_ac", pytesseract.image_to_string(g)


def ocr_variants_escalated(path):
    img = Image.open(path)
    g = ImageOps.autocontrast(img.convert("L"))
    for scale in (2, 3):
        w, h = g.size
        up = g.resize((w * scale, h * scale), Image.LANCZOS)
        for psm in (6, 4, 11):
            try:
                yield f"up{scale}_psm{psm}", pytesseract.image_to_string(up, config=f"--psm {psm}")
            except Exception:
                pass


# ---------------- Date extraction ----------------

DATE_PATTERNS = [
    # YYYY-MM-DD
    (re.compile(r"\b(\d{4})[-/](\d{1,2})[-/](\d{1,2})\b"), "ymd"),
    # DD-MM-YYYY or DD/MM/YYYY
    (re.compile(r"\b(\d{1,2})[-/](\d{1,2})[-/](\d{4})\b"), "dmy4"),
    # DD-MM-YY or DD/MM/YY
    (re.compile(r"\b(\d{1,2})[-/](\d{1,2})[-/](\d{2})\b"), "dmy2"),
    # DD Mon YYYY
    (re.compile(r"\b(\d{1,2})[\s\-]+([A-Za-z]{3,9})[\s\-,]+(\d{4})\b"), "dmony"),
]


def parse_date_matches(text):
    """Return list of (iso_date, line_text, label_present_bool) found in text."""
    results = []
    lines = text.splitlines()
    for lineno, line in enumerate(lines):
        label = bool(re.search(r"\b(date|tarikh|tanggal)\b", line, re.IGNORECASE))
        for pat, kind in DATE_PATTERNS:
            for m in pat.finditer(line):
                try:
                    if kind == "ymd":
                        y, mo, d = int(m.group(1)), int(m.group(2)), int(m.group(3))
                    elif kind == "dmy4":
                        d, mo, y = int(m.group(1)), int(m.group(2)), int(m.group(3))
                    elif kind == "dmy2":
                        d, mo, yy = int(m.group(1)), int(m.group(2)), int(m.group(3))
                        y = 2000 + yy
                    elif kind == "dmony":
                        d = int(m.group(1))
                        mon_s = m.group(2).lower()[:4] if m.group(2).lower().startswith('sept') else m.group(2).lower()[:3]
                        if mon_s not in MONTHS:
                            continue
                        mo = MONTHS[mon_s]
                        y = int(m.group(3))
                    else:
                        continue
                    if not (1 <= mo <= 12 and 1 <= d <= 31 and 1900 <= y <= 2099):
                        continue
                    # Avoid picking up times adjacent
                    iso = f"{y:04d}-{mo:02d}-{d:02d}"
                    results.append((iso, line, label, lineno))
                except Exception:
                    continue
    return results


def pick_date(passes):
    """passes: list of OCR text strings"""
    # Collect candidates with pass counts
    all_candidates = []  # list of (iso, label, line)
    for text in passes:
        for iso, line, label, lineno in parse_date_matches(text):
            all_candidates.append((iso, label, line))

    if not all_candidates:
        return None

    # Prefer labelled
    labelled = [c for c in all_candidates if c[1]]
    if labelled:
        # Return the most common labelled iso
        from collections import Counter
        cnt = Counter(c[0] for c in labelled)
        return cnt.most_common(1)[0][0]

    # Fallback: earliest valid non-time-adjacent appearing in >=2 passes
    from collections import Counter
    per_pass_sets = []
    for text in passes:
        s = set()
        for iso, line, label, lineno in parse_date_matches(text):
            s.add(iso)
        per_pass_sets.append(s)
    pass_count = Counter()
    for s in per_pass_sets:
        for iso in s:
            pass_count[iso] += 1
    multi = [iso for iso, c in pass_count.items() if c >= 2]
    if multi:
        # Return earliest by date value
        return sorted(multi)[0]

    # Else return the first candidate
    return all_candidates[0][0]


# ---------------- Total extraction ----------------

def find_numbers(s):
    nums = []
    for m in NUM_RE.finditer(s):
        tok = m.group(0).replace(",", "")
        try:
            nums.append((float(tok), tok))
        except ValueError:
            pass
    return nums


def line_has_any(line_up, keywords):
    for kw in keywords:
        if kw in line_up:
            return True
    return False


def is_excluded_line(line_up):
    for kw in EXCLUSION_KEYWORDS:
        if kw in line_up:
            return True
    # If line looks like payment/tender/change/card/received context
    for kw in PAYMENT_EXCLUDE:
        if kw in line_up:
            return True
    return False


def extract_tier_candidates(text):
    """Return dict: tier_idx -> list of (value_float, value_str) found in that tier."""
    results = {i: [] for i in range(len(TIER_KEYWORDS))}
    lines = text.splitlines()
    for i, line in enumerate(lines):
        up = line.upper()
        # Determine which tier applies to this line (choose highest tier whose keyword appears)
        matched_tier = None
        for tier_idx in range(len(TIER_KEYWORDS) - 1, -1, -1):
            if line_has_any(up, TIER_KEYWORDS[tier_idx]):
                matched_tier = tier_idx
                break
        if matched_tier is None:
            continue
        # Check exclusions: subtotal/tax etc should skip
        # Only apply exclusions when they're not the same word as the matched keyword
        # Example: SUBTOTAL contains TOTAL but we must skip. Check exclusion first.
        excluded = False
        for kw in EXCLUSION_KEYWORDS:
            if kw in up:
                excluded = True
                break
        if excluded:
            continue
        # Also skip payment lines
        is_payment = False
        for kw in PAYMENT_EXCLUDE:
            if kw in up:
                is_payment = True
                break
        if is_payment:
            continue

        nums = find_numbers(line)
        if nums:
            # Use last number on this line
            val, s = nums[-1]
            results[matched_tier].append((val, s))
        else:
            # fallback to next non-excluded line
            for j in range(i + 1, min(i + 3, len(lines))):
                nxt = lines[j]
                nxt_up = nxt.upper()
                if is_excluded_line(nxt_up):
                    continue
                nxt_nums = find_numbers(nxt)
                if nxt_nums:
                    val, s = nxt_nums[-1]
                    results[matched_tier].append((val, s))
                    break
    return results


def compute_anchors(text):
    """Compute anchor set A: Subtotal, Total Incl GST, Rounded/Net, |Payment/Visa/Mastercard/Cash|, (Cash-Change)."""
    anchors = []
    lines = text.splitlines()
    cash_val = None
    change_val = None
    for line in lines:
        up = line.upper()
        nums = find_numbers(line)
        if not nums:
            continue
        val = nums[-1][0]
        if "SUBTOTAL" in up or "SUB TOTAL" in up:
            anchors.append(val)
        if "TOTAL INCL" in up or ("INCL" in up and "GST" in up):
            anchors.append(val)
        if "ROUNDED" in up or "NET TOTAL" in up or "ROUNDING" in up and "ADJ" not in up:
            if "ADJ" not in up:
                anchors.append(val)
        if "PAYMENT" in up or "VISA" in up or "MASTERCARD" in up:
            if "CHANGE" not in up and "TENDERED" not in up:
                anchors.append(abs(val))
        if "CASH" in up and "CHANGE" not in up and "TENDERED" not in up:
            cash_val = val
            anchors.append(abs(val))
        if "CHANGE" in up:
            change_val = val
    if cash_val is not None and change_val is not None:
        anchors.append(cash_val - change_val)
    return [a for a in anchors if a > 0]


def pick_total(passes):
    """passes: list of OCR text strings"""
    # Collect tier candidates per pass
    from collections import Counter
    tier_candidates = {i: [] for i in range(len(TIER_KEYWORDS))}
    all_anchors = []
    for text in passes:
        tc = extract_tier_candidates(text)
        for i, cs in tc.items():
            tier_candidates[i].extend(cs)
        all_anchors.extend(compute_anchors(text))

    # Determine highest-priority tier that has any candidate
    chosen_tier = None
    for tier_idx in range(len(TIER_KEYWORDS) - 1, -1, -1):
        if tier_candidates[tier_idx]:
            chosen_tier = tier_idx
            break

    if chosen_tier is None:
        # No tier matched. If >=2 anchors agree within 0.05, emit that
        if len(all_anchors) >= 2:
            max_a = max(all_anchors)
            groups = []
            for a in all_anchors:
                placed = False
                for g in groups:
                    if abs(g[0] - a) <= 0.05:
                        g.append(a)
                        placed = True
                        break
                if not placed:
                    groups.append([a])
            for g in groups:
                if len(g) >= 2:
                    v = sum(g) / len(g)
                    return f"{v:.2f}"
        return None

    cands = tier_candidates[chosen_tier]

    # Filter outliers using anchors
    if all_anchors:
        max_a = max(all_anchors)
        anchor_leading_digits = set(str(int(a))[0] for a in all_anchors if a >= 1)
        filtered = []
        for val, s in cands:
            lead = str(int(val))[0] if val >= 1 else "0"
            if anchor_leading_digits and lead not in anchor_leading_digits:
                # skip outlier
                continue
            if val > 2 * max_a:
                continue
            filtered.append((val, s))
        if filtered:
            cands = filtered

    # Prefer a value equal (within 0.05) to any anchor
    if all_anchors:
        for val, s in cands:
            for a in all_anchors:
                if abs(val - a) <= 0.05:
                    return f"{val:.2f}"

    # Else: most common value
    cnt = Counter(round(v, 2) for v, _ in cands)
    most, _ = cnt.most_common(1)[0]
    return f"{most:.2f}"


# ---------------- Main ----------------

def process_image(path):
    passes = []
    for name, text in ocr_variants(path):
        passes.append(text)

    date = pick_date(passes)
    total = pick_total(passes)

    # Escalate if either missing
    if date is None or total is None:
        for name, text in ocr_variants_escalated(path):
            passes.append(text)
            d2 = pick_date(passes)
            t2 = pick_total(passes)
            if d2 is not None and t2 is not None:
                date = d2
                total = t2
                break
            date = d2 if date is None else date
            total = t2 if total is None else total

    return date, total


def main():
    files = sorted(glob.glob(os.path.join(IMG_DIR, "*.jpg")) +
                   glob.glob(os.path.join(IMG_DIR, "*.jpeg")) +
                   glob.glob(os.path.join(IMG_DIR, "*.png")))
    files = sorted(files, key=lambda p: os.path.basename(p))

    rows = []
    for fp in files:
        fn = os.path.basename(fp)
        try:
            d, t = process_image(fp)
        except Exception as e:
            print(f"Error on {fn}: {e}")
            d, t = None, None
        print(f"{fn}: date={d}, total={t}")
        rows.append((fn, d, t))

    wb = Workbook()
    ws = wb.active
    ws.title = "results"
    ws.append(["filename", "date", "total_amount"])
    for fn, d, t in rows:
        ws.append([fn, d, t])
    wb.save(OUT_XLSX)
    print(f"Saved {OUT_XLSX}")


if __name__ == "__main__":
    main()
